prioritization, plus the AFLFast fuzzer built on the AFL core.

The Markov chain model: each unique execution path (coverage set) is a
state. Mutating an input exercising path i may produce an input exercising
path j — a state transition. f(i) counts generated inputs exercising path
i; s(i) counts how often the seed for path i was selected for fuzzing.
"""

from typing import Dict, List, Optional, Sequence, Set, Tuple

from fuzzsim.afl_fuzzer import AFLFuzzer
from fuzzsim.aflfast_schedules import (
    COE, EXPLORE, FAST, LINEAR, QUAD, EnergyComputer,
)
from fuzzsim.seed import TestCase


class PathFrequencyTracker:
    """Tracks Markov states (paths), their frequencies and transitions."""

    def __init__(self, rare_threshold: int = 2):
        self.state_ids: Dict[frozenset, int] = {}
        self.frequencies: Dict[int, int] = {}       # f(i)
        self.selection_counts: Dict[int, int] = {}  # s(i)
        self.transitions: Dict[Tuple[int, int], int] = {}
        self.rare_threshold = rare_threshold

    def identify_state(self, coverage: Set[int]) -> int:
        """Map a coverage set to its Markov state id (first-seen order)."""
        key = frozenset(coverage)
        if key not in self.state_ids:
            sid = len(self.state_ids)
            self.state_ids[key] = sid
            self.frequencies[sid] = 0
            self.selection_counts[sid] = 0
        return self.state_ids[key]

    def record_execution(self, coverage: Set[int],
                         parent_state: Optional[int] = None) -> int:
        """Record one generated input exercising `coverage`'s path."""
        sid = self.identify_state(coverage)
        self.frequencies[sid] += 1
        if parent_state is not None and parent_state != sid:
            key = (parent_state, sid)
            self.transitions[key] = self.transitions.get(key, 0) + 1
        return sid

    def record_selection(self, state: int) -> None:
        """Record that the seed for `state` was chosen (s(i) += 1)."""
        self.selection_counts[state] = self.selection_counts.get(state, 0) + 1

    def transition_probability(self, from_state: int, to_state: int) -> float:
        """Estimated P(transition from_state -> to_state)."""
        total = sum(c for (a, _), c in self.transitions.items() if a == from_state)
        if total == 0:
            return 0.0
        return self.transitions.get((from_state, to_state), 0) / total

    def is_rare(self, state: int) -> bool:
        """A path is rare if few generated inputs have exercised it."""
        return self.frequencies.get(state, 0) <= self.rare_threshold

    def rare_states(self) -> List[int]:
        return [s for s in self.frequencies if self.is_rare(s)]

    def frequency(self, state: int) -> int:
        return self.frequencies.get(state, 0)

    def selections(self, state: int) -> int:
        return self.selection_counts.get(state, 0)


