                       tracker: PathFrequencyTracker) -> List[TestCase]:
    """Order seeds by ascending selection count s(i) (used by FAST and COE)."""
    return sorted(queue, key=lambda tc: (tracker.selections(_seed_state(tc, tracker)),
                                         tc.creation_time))


