                       tracker: PathFrequencyTracker) -> List[TestCase]:
    """Order seeds by ascending path frequency f(i) (explore/linear/quad)."""
    return sorted(queue, key=lambda tc: (tracker.frequency(_seed_state(tc, tracker)),
                                         tc.creation_time))


class AFLFastFuzzer(AFLFuzzer):
    """AFL core fuzzer driven by AFLFast Markov-chain power schedules."""

    def __init__(self, target, seeds: List[bytes], seed: int = 42,
                 schedule: str = FAST, max_energy: float = 256.0,
                 **kwargs):
        self.schedule = schedule
        self.energy_computer = EnergyComputer(max_energy=max_energy)
        self.tracker = PathFrequencyTracker()
        self.energy_history: List[float] = []
        super().__init__(target, seeds, seed=seed, **kwargs)

    # -- execution tracking -------------------------------------------------

    def _execute(self, data: bytes):
        edges, is_crash, exec_time = super()._execute(data)
        self.tracker.record_execution(edges)
        return edges, is_crash, exec_time

    # -- energy -------------------------------------------------------------

    def assign_energy(self, tc: TestCase) -> int:
        sid = _seed_state(tc, self.tracker)
        f = self.tracker.frequency(sid)
        s = self.tracker.selections(sid)
        mu = self.energy_computer.mean_frequency(list(self.tracker.frequencies.values()))
        energy = self.energy_computer.compute(self.schedule, f, s, mu)
        self.energy_history.append(energy)
        return int(energy)

    # -- seed selection with prioritization ----------------------------------

    def _prioritized_queue(self) -> List[TestCase]:
        if self.schedule in (FAST, COE):
            return prioritize_small_s(self.queue, self.tracker)
        if self.schedule in (EXPLORE, LINEAR, QUAD):
            return prioritize_small_f(self.queue, self.tracker)
        return list(self.queue)

    def fuzz_one(self, tc: TestCase) -> None:
        sid = _seed_state(tc, self.tracker)
        self.tracker.record_selection(sid)
        parent_state = sid
        tc.times_chosen += 1
        if not tc.was_fuzzed:
            self.deterministic_stages(tc)
            tc.was_fuzzed = True
            tc.fuzz_count += 1
            return
