            self.tracker.record_execution(edges, parent_state)
        return super()._try(data, stage, parent)

    def run(self, max_cycles: int = 5) -> None:
        for _ in range(max_cycles):
            self.cull_corpus()
            for tc in self._prioritized_queue():
                self.fuzz_one(tc)

    @property
    def mean_energy(self) -> float:
        if not self.energy_history:
            return 0.0
        return sum(self.energy_history) / len(self.energy_history)

