"""AFLGo distance computation: two-level (function / basic-block) distances.

Function-level distance: BFS on the reverse call graph starting from the
target functions. Basic-block level distance: BFS shortest paths on the
CFG, combined with the containing function's distance via the harmonic
mean (AFLGo's formula). Distances are normalized to [0, 1]; a seed's
distance is the minimum block distance among the blocks of the edges it
covers.
"""

from collections import deque
from typing import Dict, List, Optional, Set

from fuzzsim.seed import TestCase


class CallGraph:
    """Directed call graph with function/edge management."""

    def __init__(self):
        self.functions: Set[int] = set()
        self.calls: Set[tuple] = set()
        self.callees: Dict[int, Set[int]] = {}
        self.callers: Dict[int, Set[int]] = {}

    def add_function(self, func: int) -> None:
        self.functions.add(func)
        self.callees.setdefault(func, set())
        self.callers.setdefault(func, set())

    def add_call(self, caller: int, callee: int) -> None:
        self.add_function(caller)
        self.add_function(callee)
        self.calls.add((caller, callee))
        self.callees[caller].add(callee)
        self.callers[callee].add(caller)

    def function_distances(self, targets: List[int]) -> Dict[int, float]:
        """BFS on the reverse call graph from the target functions.

        Returns {function: distance to nearest target function}; functions
        that cannot reach a target get distance inf.
        """
        dist: Dict[int, float] = {f: float("inf") for f in self.functions}
        queue = deque()
        for t in targets:
            if t in self.functions:
                dist[t] = 0.0
                queue.append(t)
        while queue:
            node = queue.popleft()
            for caller in self.callers.get(node, ()):
                if dist[node] + 1.0 < dist[caller]:
                    dist[caller] = dist[node] + 1.0
                    queue.append(caller)
        return dist


class CFGDistance:
    """BFS-based shortest-path distances on a control flow graph."""

    def __init__(self, edges: List, blocks: Optional[List[int]] = None):
        # edges: iterable of objects with .src / .dst
        self.succ: Dict[int, Set[int]] = {}
        self.pred: Dict[int, Set[int]] = {}
        block_set: Set[int] = set(blocks or [])
        for e in edges:
            self.succ.setdefault(e.src, set()).add(e.dst)
            self.pred.setdefault(e.dst, set()).add(e.src)
            block_set.add(e.src)
            block_set.add(e.dst)
        self.blocks = block_set

    def shortest_distances(self, target_blocks: List[int]) -> Dict[int, float]:
        """Reverse BFS from target blocks; inf for unreachable blocks."""
        dist: Dict[int, float] = {b: float("inf") for b in self.blocks}
        queue = deque()
        for t in target_blocks:
            if t in self.blocks:
                dist[t] = 0.0
                queue.append(t)
        while queue:
            node = queue.popleft()
            for p in self.pred.get(node, ()):
                if dist[node] + 1.0 < dist[p]:
                    dist[p] = dist[node] + 1.0
                    queue.append(p)
        return dist


def harmonic_mean(a: float, b: float) -> float:
    """Harmonic mean combining CFG and function distances."""
    if a == float("inf") or b == float("inf"):
        return float("inf")
    if a == 0.0 and b == 0.0:
        return 0.0
    return 2.0 * a * b / (a + b)


class DistanceComputer:
    """Orchestrates the full AFLGo distance pipeline for a program."""

    def __init__(self, program, target_blocks: Optional[List[int]] = None):
        self.program = program
        self.target_blocks = list(
            target_blocks if target_blocks is not None else program.target_blocks)

        # In this simulation each basic block is its own function and CFG
        # edges are the call edges, so the two levels agree and the
        # harmonic-mean combination is exact.
        self.call_graph = CallGraph()
        for b in program.blocks:
            self.call_graph.add_function(b)
        for e in program.edges:
            self.call_graph.add_call(e.src, e.dst)

        self.cfg = CFGDistance(program.edges, list(program.blocks))
        self.block_to_function: Dict[int, int] = {b: b for b in program.blocks}

        self.function_distances = self.call_graph.function_distances(
            self.target_blocks)
        self.cfg_distances = self.cfg.shortest_distances(self.target_blocks)

        # Basic-block distance: harmonic mean of CFG and function distance.
        self.block_distances: Dict[int, float] = {
            b: harmonic_mean(self.cfg_distances[b],
                             self.function_distances[self.block_to_function[b]])
            for b in program.blocks
        }
        self.normalized: Dict[int, float] = self._normalize(self.block_distances)

    @staticmethod
    def _normalize(distances: Dict[int, float]) -> Dict[int, float]:
        """Normalize distances to [0, 1]; unreachable blocks map to 1.0."""
        finite = [d for d in distances.values() if d != float("inf")]
        if not finite:
            return {b: 0.0 for b in distances}
        dmin, dmax = min(finite), max(finite)
        span = dmax - dmin
        out: Dict[int, float] = {}
        for b, d in distances.items():
            if d == float("inf"):
                out[b] = 1.0
            elif span == 0.0:
                out[b] = 0.0
            else:
                out[b] = (d - dmin) / span
        return out

    def seed_distance(self, tc: TestCase) -> float:
        """Minimum normalized block distance among the seed's covered edges."""
        best = 1.0
        found = False
        for e in self.program.edges:
            if e.edge_id in tc.coverage:
                for b in (e.src, e.dst):
                    d = self.normalized.get(b, 1.0)
                    if d < best:
                        best = d
                        found = True
        return best if found else 1.0

    def seed_distances(self, queue: List[TestCase]) -> Dict[int, float]:
        """{queue index: normalized seed distance} for the whole queue."""
        return {i: self.seed_distance(tc) for i, tc in enumerate(queue)}

    def accuracy_vs(self, reference: Dict[int, float]) -> float:
        """Percentage of blocks whose distance matches a reference map."""
        if not self.block_distances:
            return 0.0
        matches = sum(
            1 for b, d in self.block_distances.items()
            if reference.get(b, float("inf")) == d
        )
        return matches / len(self.block_distances) * 100.0

