"""AFLGo simulated annealing and the directed greybox fuzzer.

The annealing temperature drives the exploration-to-exploitation
transition. Energy assignment:

    p(s, T) = base * ((1 - d(s)) * (1 - T) + 0.5 * T)

so at T=1 (hot, exploration) every seed gets base * 0.5 (uniform), and at
T=0 (cold, exploitation) energy is proportional to (1 - d(s)) — closer
seeds get more energy. Seeds far from the target (d > 0.9) are skipped
during the exploitation phase (T < 0.3).

Cooling schedules:
- exponential:  T(t) = T0 * alpha ** (t / t_x * K)
- linear:       T(t) = T0 * (1 - t / t_x)
- logarithmic:  T(t) = T0 / (1 + log(1 + t / t_x * K))
- adaptive:     exponential, but alpha is adjusted based on recent
                progress (new coverage per iteration).
"""

import math
from typing import List, Optional

from fuzzsim.afl_fuzzer import AFLFuzzer
from fuzzsim.aflgo_distance import DistanceComputer
from fuzzsim.seed import TestCase

EXPLOITATION_THRESHOLD = 0.3   # T below this: exploitation phase
TRANSITION_THRESHOLD = 0.6     # T below this (but >= 0.3): transition
SKIP_DISTANCE = 0.9            # seeds farther than this are skipped when cold


class CoolingSchedule:
    """Base class for cooling schedules."""

    def __init__(self, t0: float = 1.0, t_x: float = 1000.0, k: float = 10.0,
                 alpha: float = 0.1):
        self.t0 = t0
        self.t_x = max(t_x, 1e-9)
        self.k = k
        self.alpha = alpha

    def temperature(self, t: float) -> float:
        raise NotImplementedError

    def report_progress(self, new_coverage: int) -> None:
        """Hook used by adaptive schedules."""


class ExponentialCooling(CoolingSchedule):
    """T(t) = T0 * alpha^(t/t_x * K) — AFLGo's default schedule."""

    def temperature(self, t: float) -> float:
        x = min(max(t / self.t_x, 0.0), 1.0)
        return self.t0 * (self.alpha ** (x * self.k))


class LinearCooling(CoolingSchedule):
    """T(t) = T0 * (1 - t/t_x)."""

    def temperature(self, t: float) -> float:
        x = min(max(t / self.t_x, 0.0), 1.0)
        return self.t0 * (1.0 - x)


class LogarithmicCooling(CoolingSchedule):
    """T(t) = T0 / (1 + log(1 + t/t_x * K))."""

    def temperature(self, t: float) -> float:
        x = min(max(t / self.t_x, 0.0), 1.0)
        return self.t0 / (1.0 + math.log(1.0 + x * self.k))


class AdaptiveCooling(ExponentialCooling):
    """Exponential cooling whose alpha adapts to recent progress.

    If recent iterations produced new coverage, cooling slows down (alpha
    moves toward 1) to keep exploring; without progress it cools faster.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.base_alpha = self.alpha
        self._progress_window: List[int] = []
        self.window = 64

    def report_progress(self, new_coverage: int) -> None:
        self._progress_window.append(new_coverage)
        if len(self._progress_window) > self.window:
            self._progress_window.pop(0)
        hits = sum(self._progress_window)
        if hits > 0:
            # slow down cooling while progress is being made
            self.alpha = min(1.0, self.base_alpha * (1.0 + 0.1 * hits))
        else:
            self.alpha = self.base_alpha


def phase_of(temperature: float) -> str:
    """Classify the annealing phase from the current temperature."""
    if temperature >= TRANSITION_THRESHOLD:
        return "exploration"
    if temperature >= EXPLOITATION_THRESHOLD:
        return "transition"
    return "exploitation"


class SimulatedAnnealing:
    """Temperature-based energy assignment for directed fuzzing."""

    def __init__(self, schedule: CoolingSchedule, base_energy: float = 32.0):
        self.schedule = schedule
        self.base_energy = base_energy

    def temperature(self, t: float) -> float:
        return self.schedule.temperature(t)

    def energy(self, distance: float, temperature: float) -> float:
        """p(s, T) = base * ((1 - d(s)) * (1 - T) + 0.5 * T)."""
        d = min(max(distance, 0.0), 1.0)
        t = min(max(temperature, 0.0), 1.0)
        return self.base_energy * ((1.0 - d) * (1.0 - t) + 0.5 * t)

    def should_skip(self, distance: float, temperature: float) -> bool:
        """Skip far-away seeds during the exploitation phase."""
        return temperature < EXPLOITATION_THRESHOLD and distance > SKIP_DISTANCE

    def phase(self, temperature: float) -> str:
        return phase_of(temperature)


class AFLGoFuzzer(AFLFuzzer):
    """Directed greybox fuzzer: distance-aware energy + annealing schedule."""

    def __init__(self, target, seeds: List[bytes], seed: int = 42,
                 target_blocks: Optional[List[int]] = None,
                 schedule: Optional[CoolingSchedule] = None,
                 base_energy: float = 32.0, directed: bool = True,
                 **kwargs):
        self.distance_computer = DistanceComputer(target.program, target_blocks)
        self.annealing = SimulatedAnnealing(
            schedule or ExponentialCooling(), base_energy=base_energy)
        self.directed = directed
        self.time = 0
        self.first_crash_iteration: Optional[int] = None
        self.seed_distance_cache: Dict[int, float] = {}
        super().__init__(target, seeds, seed=seed, **kwargs)

    # -- energy / skipping ----------------------------------------------------

    def assign_energy(self, tc: TestCase) -> int:
        if not self.directed:
            return int(self.annealing.base_energy)
        t = self.annealing.temperature(self.time)
        d = self.distance_computer.seed_distance(tc)
        return max(1, int(round(self.annealing.energy(d, t))))

    def _should_skip_seed(self, tc: TestCase) -> bool:
        if not self.directed:
            return False
        t = self.annealing.temperature(self.time)
        d = self.distance_computer.seed_distance(tc)
        return self.annealing.should_skip(d, t)

    # -- main loop with TTE tracking -------------------------------------------

    def _try(self, data: bytes, stage: str, parent: Optional[TestCase]) -> bool:
        before = len(self.crashes)
        added = super()._try(data, stage, parent)
        if len(self.crashes) > before and self.first_crash_iteration is None:
            self.first_crash_iteration = self.time
        if added:
            self.annealing.schedule.report_progress(1)
        return added

    def fuzz_one(self, tc: TestCase) -> None:
        tc.times_chosen += 1
        if not tc.was_fuzzed:
            self.deterministic_stages(tc)
            tc.was_fuzzed = True
            tc.fuzz_count += 1
            return
        if self._should_skip_seed(tc):
            return
        energy = self.assign_energy(tc)
        tc.fuzz_count += energy
        for _ in range(energy):
            self.iteration += 1
            self.time += 1
            self._try(self.havoc_mutation(tc.data), "havoc", tc)
            if self.rng.random_sample() < 0.25:
                spliced = self.splice(tc)
                if spliced is not None:
                    self.time += 1
                    self._try(spliced, "splice", tc)

    def run_until_crash(self, max_time: int = 20000) -> Optional[int]:
        """Run until the first (deduplicated) crash; return its iteration."""
        while self.first_crash_iteration is None and self.time < max_time:
            self.cull_corpus()
            snapshot = list(self.queue)
            progressed = False
            for tc in snapshot:
                self.fuzz_one(tc)
                progressed = True
                if self.first_crash_iteration is not None:
                    break
            if not progressed:
                break
        return self.first_crash_iteration

