from fuzzsim.aflgo_annealing import AFLGoFuzzer, ExponentialCooling
from fuzzsim.targets.crashme import CrashmeProgram

class ScanFuzzer(AFLGoFuzzer):
    def __init__(self, *a, sp=0.25, **k):
        self.sp = sp
        super().__init__(*a, **k)
    def fuzz_one(self, tc):
        tc.times_chosen += 1
        if not tc.was_fuzzed:
            self.deterministic_stages(tc); tc.was_fuzzed = True; tc.fuzz_count += 1; return
        if self._should_skip_seed(tc): return
        energy = self.assign_energy(tc)
        tc.fuzz_count += energy
        for _ in range(energy):
            self.iteration += 1; self.time += 1
            self._try(self.havoc_mutation(tc.data), "havoc", tc)
            if self.rng.random_sample() < self.sp:
                s = self.splice(tc)
                if s is not None:
                    self.time += 1
                    self._try(s, "splice", tc)

seeds=[b'\x00\x00\x00\x00', b'\x01\x00\x00\x00', b'\x02\x00\x00\x00']
